import "bootstrap/dist/css/bootstrap.min.css";
import { Modal, Tooltip } from "bootstrap";

for (const element of document.querySelectorAll('[data-bs-toggle="tooltip"]')) {
  new Tooltip(element);
}

const confirmElement = document.querySelector("#confirm");

confirmElement.addEventListener("shown.bs.modal", () => {
  confirmElement.querySelector(".btn-secondary").focus();
});

document.querySelector("#trip-list").addEventListener("keydown", (event) => {
  if (event.key === "Delete") {
    Modal.getOrCreateInstance(confirmElement).show();
  }
});

const dark = window.matchMedia("(prefers-color-scheme: dark)");

function savedTheme() {
  try {
    return localStorage.getItem("theme");
  } catch {
    return null;
  }
}

function applyTheme() {
  const theme = savedTheme() ?? (dark.matches ? "dark" : "light");
  document.documentElement.dataset.bsTheme = theme;
}

applyTheme();
dark.addEventListener("change", applyTheme);

document.addEventListener("DOMContentLoaded", () => {
  document.querySelector("#theme-toggle").addEventListener("click", () => {
    const next = document.documentElement.dataset.bsTheme === "dark" ? "light" : "dark";
    try {
      localStorage.setItem("theme", next);
    } catch {}
    applyTheme();
  });
});
